<ResourceLayout v-else :wide="wide"><template #left><a-card class="info"><FileTextOutlined class="icon"/><h3>sharedfs-client-policy-design</h3><a-badge status="success" text="사용 가능"/><dl><dt>주 IP</dt><dd>10.10.13.240 (예시)</dd><dt>기본 DATA</dt><dd>10 GiB · SPARSE XFS (예시)</dd><dt>계정</dt><dd>admin</dd><dt>Zone</dt><dd>13-Zone</dd></dl></a-card></template>
