<a-table :columns="columns" :data-source="rows" row-key="id" size="small" :pagination="false" :scroll="{x:850}"><template #bodyCell="{column,record}"><a v-if="column.key==='local'" @click="dialog=true">{{record.local}}</a><template v-else-if="column.key==='apply'"><a-tag :color="scenario==='failed'&&record.id==='team'?'red':scenario==='unknown'?'default':'green'">{{record.apply}}</a-tag></template></template></a-table>
