<script>
import koKR from 'ant-design-vue/es/locale/ko_KR'
import Breadcrumb from '@/components/widgets/Breadcrumb.vue'
import ResourceLayout from '@/layouts/ResourceLayout.vue'
import MoldDialog from '@/components/view/MoldDialog.vue'
import {ReloadOutlined,PlusOutlined,DownOutlined,FileTextOutlined,FileSearchOutlined,FullscreenOutlined} from '@ant-design/icons-vue'
const q=new URLSearchParams(location.search)
export default {components:{Breadcrumb,ResourceLayout,MoldDialog,ReloadOutlined,PlusOutlined,DownOutlined,FileTextOutlined,FileSearchOutlined,FullscreenOutlined},
data(){return {locale:koKR,view:q.get('view')||'nfs',scenario:q.get('scenario')||'external',dark:q.get('theme')==='dark',dialog:q.get('dialog')==='diagnostic',updated:false,wide:false,listColumns:[{title:'이름',key:'name',dataIndex:'name',width:300},{title:'상태',key:'state',width:120},{title:'스토리지 용량',dataIndex:'capacity',width:180},{title:'계정',dataIndex:'account',width:100},{title:'Zone',dataIndex:'zone',width:100}],listRows:[{id:'design',name:'sharedfs-client-policy-design',state:'사용 가능',capacity:'10 GiB · DATA 1',account:'admin',zone:'13-Zone'}],columns:[{title:'내보내기 / 포트',dataIndex:'name',width:170},{title:'설정 적용',key:'apply',dataIndex:'apply',width:130},{title:'로컬 접근 점검',key:'local',dataIndex:'local',width:180},{title:'외부 접속 확인',dataIndex:'external',width:160},{title:'관측 시각',dataIndex:'time',width:160}]}},
watch:{view(v){this.$router.push(v==='list'?'/sharedfs':'/sharedfs/design-client-policy')},dark:{immediate:true,handler(v){document.body.classList.toggle('dark-mode',v)}}},
computed:{alertType(){return {external:'info',verified:'success',failed:'error',unknown:'warning'}[this.scenario]},headline(){return {external:'설정 적용 완료 · 외부 클라이언트 확인 필요',verified:'설정 적용 완료 · 로컬 점검 완료',failed:'NFS 설정 적용 실패 · 이전 정책 복구 완료 (예시)',unknown:'현재 접근 점검을 확인할 수 없습니다.'}[this.scenario]},description(){return {external:'서버 주소가 사용자 ACL에 없어 로컬 마운트 점검을 수행하지 않았습니다. 리스너는 유지되며, 실제 허용 클라이언트에서 접근을 확인하세요.',verified:'로컬 마운트 점검 결과입니다. 외부 클라이언트의 인증·네트워크·파일 권한까지 확인한 결과는 아닙니다.',failed:'원래 실패 코드와 원복 결과를 작업 내역에서 확인하세요. 검사 생략으로 처리하거나 정상 적용으로 표시하지 않습니다.',unknown:'이전 관측을 유지합니다. 통신 장애를 ACL 제외나 새로운 설정 실패로 판정하지 않습니다.'}[this.scenario]},applied(){return this.scenario==='failed'?'실패 · 이전 정책 복구 완료 (예시)':this.scenario==='unknown'?'이전 관측 · 적용됨':'적용됨'},local(){return {external:'ACL 제외 · 점검 미실시',verified:'마운트 점검 완료',failed:'적용 실패로 점검 불가',unknown:'현재 관측 불가'}[this.scenario]},external(){return '실제 허용 클라이언트에서 확인 필요'},rows(){return [{id:'team',name:'team · 2049/2050',apply:this.applied,local:this.local,external:'사용자 확인 필요',time:this.scenario==='unknown'?'이전 10:20:00':'예시 10:21:00'},{id:'other',name:'other · 2049',apply:this.scenario==='unknown'?'이전 관측 · 적용됨':'적용됨',local:this.scenario==='unknown'?'관측 불가 · 이전 마운트 완료':'마운트 점검 완료',external:'사용자 확인 필요',time:this.scenario==='unknown'?'이전 10:20:00':'예시 10:21:00'}]},details(){return [['이름','sharedfs-client-policy-design'],['상태','Ready'],['주 IP','10.10.13.240 (예시)'],['프로토콜','NFS · V4_ONLY / DUAL'],['DATA','10 GiB · SPARSE XFS'],['접근 점검','NFS 탭에서 확인']]},diagnostic(){return [['내보내기','team (설계 예시)'],['포트 / 프로토콜','2049·2050 / NFSv4 전용'],['설정 적용',this.applied],['로컬 접근 점검',this.local],['외부 클라이언트',this.external],['사유 코드',this.scenario==='external'?'LOCAL_ADDRESS_EXCLUDED_BY_ACL':this.scenario==='failed'?'NFS_CLIENT_RELOAD_REJECTED':this.scenario==='unknown'?'OBSERVATION_UNAVAILABLE':'MOUNT_VERIFIED'],['리스너','기존 PID·수신 포트 유지 (예시)'],['적용 방식','CLIENT 정책 갱신 · 프로세스 재시작 없음 (예시)'],['관측 시각',this.scenario==='unknown'?'이전 관측 · 예시 10:20:00':'예시 10:21:00'],['다른 공유','기존 정책·I/O 유지 (예시)'],['원래 실패 / 원복',this.scenario==='failed'?'원래 오류 보존 / 이전 정책 복구 완료 (예시)':'해당 없음'],['권한 보호','ACL·POSIX 자동 확대 없음']]}}
}
</script>
<style>
